// Draws the exhibits from window.DATA (generated by scripts/page.py) as inline SVG.
// The page only formats and plots; colours are CSS tokens, so the charts follow the theme.
"use strict";

const D = window.DATA;
const S = D.summary;
const label = Object.fromEntries(D.engines.map((e) => [e.id, e.label]));
const median = (xs) => { const s = [...xs].sort((a, b) => a - b), m = s.length >> 1; return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };
const num = (x, digits = 0) => x.toLocaleString("en-US", { minimumFractionDigits: digits, maximumFractionDigits: digits });
const sig = (x) => (x >= 10 ? num(x) : num(x, 1));
const pct = (x) => `${num(100 * x)}%`;
const range = (r, f) => `${f(r.min)}–${f(r.max)}`;
const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;");

function facts() {
  const ch = S["fast_paths-CH"], hy = S.Hypergraph, bi = S.bidirectional;
  const share = median(D.cities.map((c) => c.engines["fast_paths-CH"].core_hours_per_billion / c.engines.Hypergraph.core_hours_per_billion));
  const means = D.cuts.map((r) => 1 - r.mean_us.median);
  const wave = D.maze.bench.find((r) => r.method === "wave");
  const wins = S.cheapest_counts["fast_paths-CH"];
  const values = {
    answers: num(D.cities.length * 2 * D.provenance.queries),
    dijkstra_ch: sig(S.dijkstra.core_hours_per_billion.median),
    hyper_ch: sig(hy.core_hours_per_billion.median),
    ch_ch: sig(ch.core_hours_per_billion.median),
    ch_wins: wins === D.cities.length ? `all ${wins}` : `${wins} of ${D.cities.length}`,
    ch_vs_hyper: pct(share),
    ch_build: `${range(ch.build_s, (x) => num(x, 1))} seconds`,
    cut_mean: `${num(100 * Math.min(...means))}–${num(100 * Math.max(...means))}%`,
    carry_max: pct(Math.max(...D.order.map((o) => o.carryover_share))),
    bidi_saving: pct(1 - bi.cost_index.median / 100),
    bidi_max: num(bi.cost_index.max),
    red_all: `${num(100 - S.Graph.cost_index.median)}–${num(100 - ch.cost_index.median, 1)}%`,
    red_overlay: `${num(100 - S.Graph.cost_index.median)}–${num(100 - hy.cost_index.median)}%`,
    red_ch: `${num(100 - ch.cost_index.median, 1)}%`,
    hyper_build: num(hy.build_s.median, 1),
    ch_build_med: num(ch.build_s.median, 1),
    maze_best: num(Math.min(...D.maze.published.filter((p) => p.metric === "exact" && p.kind === "learned").map((p) => Math.round(1000 - 10 * p.percent)))),
    maze_cert_us: num(D.maze.bench.find((r) => r.method === "wave + certificate").median_us, 2),
    maze_cert_heap: `${num(D.maze.bench.find((r) => r.method === "wave + certificate").heap_bytes / 1000, 1)} KB`,
    bidi_over: (() => { const c = D.cities.filter((c) => c.engines.bidirectional.cost_index > 100).map((c) => c.label); return `${c.length === 1 ? "one city" : `${c.length} cities`} (${c.join(", ")})`; })(),
    p50_wins: D.cuts.map((r) => r.p50_wins).join(", ") + ` of ${D.cities.length}`,
    maze_us: num(wave.median_us, 2),
    maze_heap: `${num(wave.heap_bytes / 1000, 1)} KB`,
    salsa: num(D.salsa.graphs),
  };
  for (const el of document.querySelectorAll("[data-fact]")) el.textContent = values[el.dataset.fact];
  const producer = document.getElementById("producer");
  producer.textContent = D.provenance.producer_sha.slice(0, 7);
  producer.href = `https://github.com/symonyeal/Exact-Routing/tree/${D.provenance.producer_sha}`;
}

function table() {
  document.querySelector("#cost-table tbody").innerHTML = D.engines.map(({ id }) => {
    const r = S[id];
    const build = r.build_s.max === 0 ? "none" : `${num(r.build_s.median, 1)} (${range(r.build_s, (x) => num(x, 1))})`;
    return `<tr><td>${label[id]}</td><td>${sig(r.core_hours_per_billion.median)} (${range(r.core_hours_per_billion, sig)})</td>` +
      `<td>${num(r.mean_us.median)} (${range(r.mean_us, (x) => num(x))})</td><td>${build}</td></tr>`;
  }).join("");
}

// SVG helpers. Width follows the container; text stays at 12-13 px.
const el = (tag, attrs, body = "") =>
  `<${tag} ${Object.entries(attrs).map(([k, v]) => `${k}="${esc(v)}"`).join(" ")}>${body}</${tag}>`;
const text = (x, y, s, attrs = {}) => el("text", { x, y, ...attrs }, esc(s));
const title = (s) => `<title>${esc(s)}</title>`;
function mount(id, w, h, body) {
  document.getElementById(id).innerHTML =
    `<svg viewBox="0 0 ${w} ${h}" width="100%" preserveAspectRatio="xMinYMin meet" class="plot">${body}</svg>`;
}
const narrow = () => document.getElementById("cost-chart").clientWidth < 600;

// Exhibit 1: cost index per engine, one dot per city, median tick, log axis.
function costChart() {
  const small = narrow(), W = small ? 400 : 960, left = small ? 128 : 210, right = W - 24, row = small ? 52 : 58, top = 24;
  const lo = Math.log10(0.2), hi = Math.log10(200);
  const X = (v) => left + (Math.log10(v) - lo) / (hi - lo) * (right - left);
  const H = top + row * D.engines.length + 46;
  let g = "";
  for (const t of [0.3, 1, 3, 10, 30, 100]) {
    g += el("line", { x1: X(t), x2: X(t), y1: top - 6, y2: top + row * D.engines.length, class: "grid" });
    g += text(X(t), top + row * D.engines.length + 18, num(t, t < 1 ? 1 : 0), { class: "tick", "text-anchor": "middle" });
  }
  g += text(left, H - 6, "Cost index, plain Dijkstra = 100 (log scale)", { class: "axis" });
  D.engines.forEach((e, i) => {
    const y = top + row * i + row / 2;
    g += text(left - 12, y + 4, small ? { dijkstra: "Plain Dijkstra", bidirectional: "Bidirectional", Graph: "Overlay, edge", Hypergraph: "Overlay, junction", "fast_paths-CH": "Contraction h." }[e.id] : e.label, { class: "cat", "text-anchor": "end" });
    for (const c of D.cities) {
      const r = c.engines[e.id];
      g += el("circle", { cx: X(r.cost_index), cy: y, r: 5, class: "dot" },
        title(`${c.label}: index ${num(r.cost_index, 2)}, ${sig(r.core_hours_per_billion)} core-hours per billion (${r.method})`));
    }
    const m = S[e.id].cost_index.median;
    g += el("line", { x1: X(m), x2: X(m), y1: y - 15, y2: y + 15, class: "median" });
    g += text(X(m), y - 19, num(m, m < 10 ? 1 : 0), { class: "value", "text-anchor": "middle" });
  });
  mount("cost-chart", W, H, g);
}

// Exhibit 3: junction/edge ratios by measure, grouped by cell size, reference line at 1.
function cutChart() {
  const measures = [["boundary", "Boundary points"], ["shortcuts", "Stored shortcuts"], ["settled", "Junctions searched"],
    ["mean_us", "Mean request time"], ["p50_us", "Median request time"], ["build_s", "Build time"]];
  const small = narrow(), W = small ? 400 : 960, left = small ? 128 : 170, right = W - 40, top = 40;
  const band = small ? 66 : 60, bar = (band - 12) / 3;
  const H = top + band * measures.length + 40;
  const X = (v) => left + v / 2.5 * (right - left);
  const cls = ["s0", "s1", "s2"];
  let g = "";
  g += text(small ? 0 : left, 16, "Maximum cell size, junctions:", { class: "legend" });
  D.cuts.forEach((r, i) => {
    const x = (small ? 196 : left + 200) + i * (small ? 66 : 80);
    g += el("rect", { x, y: 6, width: 12, height: 12, class: cls[i] });
    g += text(x + 18, 16, num(r.bound), { class: "legend" });
  });
  for (const t of [0, 0.5, 1, 1.5, 2, 2.5]) {
    g += el("line", { x1: X(t), x2: X(t), y1: top - 6, y2: top + band * measures.length, class: t === 1 ? "ref" : "grid" });
    g += text(X(t), top + band * measures.length + 18, num(t, 1), { class: "tick", "text-anchor": "middle" });
  }
  g += text(left, H - 4, "Junction cut ÷ edge cut, median of eleven cities", { class: "axis" });
  measures.forEach(([k, name], j) => {
    const y0 = top + band * j + (band - 3 * bar) / 2;
    g += text(left - 10, y0 + 1.5 * bar + 4, name, { class: "cat", "text-anchor": "end" });
    D.cuts.forEach((r, i) => {
      const v = r[k];
      g += el("rect", { x: X(0), y: y0 + i * bar, width: X(v.median) - X(0), height: bar - 1, class: cls[i] },
        title(`${name}, cells up to ${num(r.bound)} junctions: median ${num(v.median, 2)}, cities ${num(v.min, 2)}–${num(v.max, 2)}`));
      g += text(X(v.median) + 5, y0 + i * bar + bar - 3, num(v.median, 2), { class: "small" });
    });
  });
  mount("cut-chart", W, H, g);
}

// Exhibit 5: share of the reported median that is the request's own search versus inherited cleanup.
function orderChart() {
  const name = { dijkstra: "plain Dijkstra", "Hypergraph-1024": "junction-cut overlay" };
  const small = narrow(), W = small ? 400 : 960, left = small ? 150 : 250, right = W - 16, top = 34, row = 40;
  const H = top + row * D.order.length + 34;
  const X = (v) => left + v * (right - left);
  let g = el("rect", { x: small ? 0 : left, y: 6, width: 12, height: 12, class: "s0" }) +
    text((small ? 0 : left) + 18, 16, "Remains", { class: "legend" }) +
    el("rect", { x: (small ? 150 : left + 190), y: 6, width: 12, height: 12, class: "ctx" }) +
    text((small ? 150 : left + 190) + 18, 16, small ? "Removed by timing cleanup apart" : "Removed when cleanup is timed separately", { class: "legend" });
  for (const t of [0, 0.25, 0.5, 0.75, 1]) {
    g += text(X(t), top + row * D.order.length + 16, pct(t), { class: "tick", "text-anchor": "middle" });
  }
  D.order.forEach((o, i) => {
    const y = top + row * i, own = o.precleared_us / o.fixed_us;
    g += text(left - 10, y + row / 2 + 4, `${o.city}, ${small ? (o.method === "dijkstra" ? "Dijkstra" : "overlay") : name[o.method]}`, { class: "cat", "text-anchor": "end" });
    g += el("rect", { x: X(0), y: y + 6, width: X(own) - X(0), height: row - 12, class: "s0" }, title(`Remaining with cleanup timed separately: ${num(o.precleared_us, 2)} µs`));
    g += el("rect", { x: X(own), y: y + 6, width: X(1) - X(own), height: row - 12, class: "ctx" },
      title(`Removed: ${pct(o.carryover_share)} of ${num(o.fixed_us, 2)} µs; previous request touched ${num(o.previous_touched)} junctions`));
    g += text(X(1) - 8, y + row / 2 + 4, `${pct(o.carryover_share)} of ${num(o.fixed_us, 1)} µs`, { class: "inbar", "text-anchor": "end" });
  });
  mount("order-chart", W, H, g);
}

// Exhibit 6: wrong answers per 1,000 test mazes, exact-match results only.
function mazeChart() {
  const rows = D.maze.published.filter((p) => p.metric === "exact")
    .map((p) => ({ label: p.method, wrong: Math.round(1000 - 10 * p.percent), mine: false }))
    .concat([{ label: "This repository", wrong: 1000 - D.maze.test.exact, mine: true }])
    .sort((a, b) => b.wrong - a.wrong);
  const small = narrow(), W = small ? 400 : 960, left = small ? 150 : 210, right = W - 50, top = 8, row = 34;
  const H = top + row * rows.length + 40;
  const X = (v) => left + v / 300 * (right - left);
  let g = "";
  for (const t of [0, 100, 200, 300]) {
    g += el("line", { x1: X(t), x2: X(t), y1: top, y2: top + row * rows.length, class: "grid" });
    g += text(X(t), top + row * rows.length + 16, num(t), { class: "tick", "text-anchor": "middle" });
  }
  g += text(left, H - 4, "Wrong answers per 1,000 test mazes", { class: "axis" });
  rows.forEach((r, i) => {
    const y = top + row * i;
    g += text(left - 10, y + row / 2 + 4, r.label, { class: r.mine ? "cat strong" : "cat", "text-anchor": "end" });
    g += el("rect", { x: X(0), y: y + 7, width: Math.max(X(r.wrong) - X(0), 0), height: row - 14, class: r.mine ? "s0" : "ctx" });
    g += text(X(r.wrong) + 6, y + row / 2 + 4, num(r.wrong), { class: r.mine ? "value" : "small" });
  });
  mount("maze-chart", W, H, g);
}

function draw() { costChart(); cutChart(); orderChart(); mazeChart(); }

facts();
table();
draw();
let width = window.innerWidth;
window.addEventListener("resize", () => {
  if ((window.innerWidth < 640) !== (width < 640)) draw();
  width = window.innerWidth;
});
